using StackExchange.Redis;

var redis = ConnectionMultiplexer.Connect("localhost:6379");
var db = redis.GetDatabase();

// String operations
await db.StringSetAsync("user:1:name", "Alice");
var name = await db.StringGetAsync("user:1:name");
Console.WriteLine(name);

// Hash operations
await db.HashSetAsync("user:1", new HashEntry[]
{
    new HashEntry("name", "Alice"),
    new HashEntry("email", "alice@example.com")
});

// Key expiration
await db.KeyExpireAsync("user:1", TimeSpan.FromHours(1));
